extension Fuzz {
extension SyntaxHashable {
  public func hash(into hasher: inout Hasher) {
    return _syntaxNode.id.hash(into: &hasher)
  }

  public static func == (lhs: Self, rhs: Self) -> Bool {
    return lhs. _syntaxNode.id == rhs._syntaxNode.id
  }
}
}

